cd /home/admin/backend && php artisan tinker --execute="
use App\Models\ClassSession;
use App\Models\StudentClass;
use Carbon\Carbon;

\$orphans = \Illuminate\Support\Facades\DB::select(\"
  SELECT sc.ID, sc.StudentID, sc.SubjectID, sc.TeacherID,
         sc.SessionCount, sc.RemainingSessions, sc.StartDate,
         sc.week, sc.time, sc.SessionDuration, sc.ClassType,
         sc.week1, sc.time1, sc.week2, sc.time2
  FROM StudentClass sc
  LEFT JOIN ClassSession cs ON cs.StudentClassID = sc.ID
  WHERE sc.ScheduleMode = 'count'
    AND sc.SessionCount > 0
    AND (sc.Stop = 0 OR sc.Stop IS NULL)
    AND cs.id IS NULL
  ORDER BY sc.ID DESC
\");

foreach (\$orphans as \$o) {
    \$startDate = Carbon::parse(\$o->StartDate)->toDateString();
    \$count = (int) \$o->SessionCount;
    \$dur = (int) (\$o->SessionDuration ?: 120);
    \$startTime = \$o->time ? substr(\$o->time, 0, 5) : '16:00';
    \$endTimeCarbon = Carbon::parse(\$startDate . ' ' . \$startTime)->addMinutes(\$dur);
    \$endTime = \$endTimeCarbon->format('H:i:s');

    // Collect weekdays from week/week1/week2 fields
    \$weekdays = [];
    foreach (['week', 'week1', 'week2'] as \$f) {
        \$v = (int) (\$o->{\$f} ?? 0);
        if (\$v >= 1 && \$v <= 7 && !in_array(\$v, \$weekdays)) \$weekdays[] = \$v;
    }
    if (empty(\$weekdays)) {
        \$weekdays = [(int) Carbon::parse(\$startDate)->dayOfWeekIso];
    }

    // Build sessions: first = startDate, rest = next matching weekday
    \$sessions = [];
    \$date = Carbon::parse(\$startDate);
    // First session always on start date
    \$sessions[] = [
        'StudentClassID' => (int) \$o->ID,
        'SessionDate' => \$date->toDateString(),
        'StartTime' => \$startTime . ':00',
        'EndTime' => \$endTime,
        'Status' => 'scheduled',
        'Note' => '',
    ];
    \$cursor = \$date->copy()->addDay();
    while (count(\$sessions) < \$count) {
        \$isoDow = \$cursor->dayOfWeekIso;
        if (in_array(\$isoDow, \$weekdays)) {
            \$et = Carbon::parse(\$cursor->toDateString() . ' ' . \$startTime)->addMinutes(\$dur)->format('H:i:s');
            \$sessions[] = [
                'StudentClassID' => (int) \$o->ID,
                'SessionDate' => \$cursor->toDateString(),
                'StartTime' => \$startTime . ':00',
                'EndTime' => \$et,
                'Status' => 'scheduled',
                'Note' => '',
            ];
        }
        \$cursor->addDay();
    }

    foreach (\$sessions as \$s) {
        ClassSession::create(\$s);
    }

    // Update EndDate
    \$last = end(\$sessions);
    StudentClass::where('ID', (int) \$o->ID)->update(['EndDate' => \$last['SessionDate']]);

    echo 'Backfilled ID=' . \$o->ID . ' sessions=' . count(\$sessions) . ' endDate=' . \$last['SessionDate'] . PHP_EOL;
}
echo 'Done.' . PHP_EOL;
"

